#!/usr/bin/env python3
import sys, os, csv, json, gzip, io, re
from datetime import datetime, timedelta, timezone, date, time as dtime
from fractions import Fraction
from decimal import Decimal
from zoneinfo import ZoneInfo

UTC = timezone.utc
EPOCH = datetime(1970, 1, 1, tzinfo=UTC)


def read_text(path):
    with open(path, 'rb') as f:
        b = f.read()
    if b[:2] == b'\x1f\x8b':
        b = gzip.decompress(b)
    t = b.decode('utf-8-sig')
    return t


def lines_of(path):
    t = read_text(path)
    return [l for l in t.replace('\r\n', '\n').replace('\r', '\n').split('\n') if l.strip() != '']


def csv_rows(path, **kw):
    return list(csv.reader(lines_of(path), **kw))


def to_epoch(dt):
    d = dt - EPOCH
    return d.days * 86400 + d.seconds


def local_to_epoch(tz, naive, fold=0):
    return to_epoch(naive.replace(tzinfo=tz, fold=fold))


def std_offset(tz):
    best = None
    for m in (1, 7):
        d = datetime(2026, m, 1, tzinfo=tz)
        if not d.dst():
            return d.utcoffset()
    return datetime(2026, 1, 1, tzinfo=tz).utcoffset()


def fold_from(abbr, ambiguous_default=0):
    a = (abbr or '').strip().upper()
    if a.endswith('DT'):
        return 0
    if a.endswith('ST'):
        return 1
    return ambiguous_default


def parse_offset(s):
    sign = 1 if s[0] == '+' else -1
    return sign * (int(s[1:3]) * 3600 + int(s[3:5]) * 60)


def norm_dir(s):
    s = str(s).strip().upper()
    return 'IN' if s in ('IN', 'I', 'K', 'CLOCK_IN') else 'OUT'


# parsers return list of (id, emp, dir, epoch)
def p_abbr(path, tz):
    out = []
    hdr = None
    for row in csv_rows(path):
        row = [c.strip() for c in row]
        if 'Badge' in row and 'Punch' in row:
            hdr = {n: i for i, n in enumerate(row)}
            continue
        if hdr is None:
            continue
        g = lambda n: row[hdr[n]]
        m = re.fullmatch(r'(\d+):(\d\d):(\d\d)\s*([AaPp][Mm])?', g('Time'))
        h, mi, s = int(m.group(1)), int(m.group(2)), int(m.group(3))
        ap = m.group(4)
        if ap:
            h = h % 12 + (12 if ap.upper() == 'PM' else 0)
        mo, d, y = g('Date').split('/')
        naive = datetime(int(y), int(mo), int(d), h, mi, s)
        ep = local_to_epoch(tz, naive, fold_from(g('Zone')))
        out.append((g('Record'), g('Badge'), norm_dir(g('Punch')), ep))
    return out


def p_epoch(path, tz):
    out = []
    schema = 1
    for l in lines_of(path):
        o = json.loads(l)
        if 'schema' in o and 'heartbeat' not in o and 'id' not in o and 'punch_id' not in o:
            schema = o['schema']
            continue
        if o.get('heartbeat'):
            continue
        if schema == 2:
            out.append((str(o['punch_id']), o['employee'], norm_dir(o['direction']), int(o['epoch_ms']) // 1000))
        else:
            if 'ts_ms' in o:
                ep = int(o['ts_ms']) // 1000
            else:
                ep = int(o['ts'])
            out.append((str(o['id']), o['emp'], norm_dir(o['dir']), ep))
    return out


def p_offset(path, tz):
    out = []
    rows = csv_rows(path, delimiter=';')
    hdr = None
    for row in rows:
        if 'punch_id' in row:
            hdr = {n: i for i, n in enumerate(row)}
            continue
        g = lambda n: row[hdr[n]]
        dt = datetime.fromisoformat(g('timestamp'))
        out.append((g('punch_id'), g('employee'), norm_dir(g('event')), to_epoch(dt)))
    return out


def p_legacy(path, tz):
    out = []
    std = int(std_offset(tz).total_seconds())
    off = std
    for l in read_text(path).replace('\r\n', '\n').replace('\r', '\n').split('\n'):
        if not l.strip():
            continue
        t = l[0]
        if t == 'H':
            o = l[13:18].strip()
            off = parse_offset(o) if o else std
        elif t == 'D':
            pid = l[1:9]
            badge = l[9:15].strip()
            d = l[15]
            dtm = l[16:30]
            naive = datetime.strptime(dtm, '%Y%m%d%H%M%S')
            ep = to_epoch(naive.replace(tzinfo=UTC)) - off
            out.append((pid, 'E' + badge, norm_dir(d), ep))
    return out


def p_de(path, tz):
    out = []
    hdr = None
    for row in csv_rows(path, delimiter='\t'):
        row = [c.strip() for c in row]
        if 'Ausweis' in row:
            hdr = {n: i for i, n in enumerate(row)}
            continue
        g = lambda n: row[hdr[n]]
        d, mo, y = g('Datum').split('.')
        hh, mm = g('Uhrzeit').split(':')[:2]
        naive = datetime(int(y), int(mo), int(d), int(hh), int(mm))
        z = g('Zeitzone').upper()
        fold = 0 if z == 'MESZ' else 1
        out.append((g('Nr'), g('Ausweis'), norm_dir(g('Buchung')), local_to_epoch(tz, naive, fold)))
    return out


def p_localcsv(path, tz):
    out = []
    hdr = None
    for row in csv_rows(path):
        row = [c.strip() for c in row]
        if 'employee_id' in row and 'direction' in row:
            hdr = {n: i for i, n in enumerate(row)}
            continue
        g = lambda n: row[hdr[n]]
        naive = datetime.strptime(g('local_time'), '%Y-%m-%d %H:%M:%S')
        out.append((g('punch_ref'), g('employee_id'), norm_dir(g('direction')), local_to_epoch(tz, naive, 0)))
    return out


def p_localjsonl(path, tz):
    out = []
    for l in lines_of(path):
        o = json.loads(l)
        p = o.get('punch')
        if not isinstance(p, dict):
            continue
        naive = datetime.strptime(p['at'], '%Y-%m-%d %H:%M:%S')
        out.append((str(p['id']), p['badge'], norm_dir(p['type']), local_to_epoch(tz, naive, 0)))
    return out


PARSERS = {'abbr-csv': p_abbr, 'epoch-jsonl': p_epoch, 'offset-csv': p_offset, 'legacy-fixed': p_legacy,
           'de-tsv': p_de, 'local-csv': p_localcsv, 'local-jsonl': p_localjsonl}


def list_files(d):
    res = []
    for root, _, fs in os.walk(d):
        for f in fs:
            res.append(os.path.join(root, f))
    return sorted(res)


def main(inp, outp):
    period = json.load(open(os.path.join(inp, 'period.json')))
    pstart = date.fromisoformat(period['start'])
    pend = date.fromisoformat(period['end'])
    cutoff = datetime.fromisoformat(period['corrections_cutoff'].replace('Z', '+00:00'))

    sites = {}
    for r in csv.DictReader(io.StringIO(read_text(os.path.join(inp, 'sites.csv')))):
        sites[r['site'].strip()] = (ZoneInfo(r['timezone'].strip()), r['format'].strip())
    employees = {}
    for r in csv.DictReader(io.StringIO(read_text(os.path.join(inp, 'employees.csv')))):
        employees[r['employee_id'].strip()] = r['home_site'].strip()
    rates = {}
    for r in csv.DictReader(io.StringIO(read_text(os.path.join(inp, 'rates.csv')))):
        rates.setdefault(r['employee_id'].strip(), []).append(
            (date.fromisoformat(r['effective_from'].strip()), Fraction(Decimal(r['hourly_rate'].strip()))))
    for v in rates.values():
        v.sort()

    # 1. collect
    punches = {}  # (site,id) -> [emp, dir, epoch]
    ever = set()
    for site, (tz, fmt) in sites.items():
        d = os.path.join(inp, 'exports', site)
        if not os.path.isdir(d):
            continue
        for f in list_files(d):
            for pid, emp, dr, ep in PARSERS[fmt](f, tz):
                k = (site, pid)
                ever.add(k)
                if k not in punches:
                    punches[k] = [emp.strip(), dr, ep]

    # 2. corrections
    corr = []
    cdir = os.path.join(inp, 'corrections')
    if os.path.isdir(cdir):
        for f in list_files(cdir):
            for r in csv.DictReader(io.StringIO(read_text(f))):
                corr.append({k: (v or '').strip() for k, v in r.items() if k})
    for c in corr:
        c['_t'] = datetime.fromisoformat(c['issued_at'].replace('Z', '+00:00'))
    corr = [c for c in corr if c['_t'] <= cutoff]
    corr.sort(key=lambda c: (c['_t'], c['correction_id']))
    applied = 0
    for c in corr:
        k = (c['site'], c['punch_id'])
        a = c['action'].lower()
        if a == 'void':
            if k in punches:
                del punches[k]
                applied += 1
        elif a == 'set':
            if k in punches:
                punches[k][2] = to_epoch(datetime.fromisoformat(c['time'].replace('Z', '+00:00')))
                applied += 1
        elif a == 'add':
            if k not in ever and c['site'] in sites:
                ever.add(k)
                punches[k] = [c['employee'], norm_dir(c['type']),
                              to_epoch(datetime.fromisoformat(c['time'].replace('Z', '+00:00')))]
                applied += 1

    byemp = {}
    for (site, pid), (emp, dr, ep) in punches.items():
        if emp not in employees:
            continue
        byemp.setdefault(emp, []).append((ep, 0 if dr == 'OUT' else 1, site, pid, dr))

    def rnd(site, ep):
        tz = sites[site][0]
        off = int(datetime.fromtimestamp(ep, UTC).astimezone(tz).utcoffset().total_seconds())
        m = (ep + off) % 360
        return ep + (360 - m if m >= 180 else -m)

    def workday(emp, ep):
        tz = sites[employees[emp]][0]
        return datetime.fromtimestamp(ep, UTC).astimezone(tz).date()

    exc = dict(open_shifts=0, orphan_outs=0, duplicates_dropped=0, corrections_applied=applied)
    res = {e: dict(shifts=0, paid_minutes=0, overtime_minutes=0, night_minutes=0, gross=0) for e in employees}
    cents = {e: Fraction(0) for e in employees}

    def night_minutes(tz, a, b):
        tot = 0
        d0 = datetime.fromtimestamp(a, UTC).astimezone(tz).date() - timedelta(days=1)
        d1 = datetime.fromtimestamp(b, UTC).astimezone(tz).date()
        d = d0
        while d <= d1:
            ws = local_to_epoch(tz, datetime.combine(d, dtime(22)))
            we = local_to_epoch(tz, datetime.combine(d + timedelta(days=1), dtime(6)))
            lo, hi = max(a, ws), min(b, we)
            if hi > lo:
                tot += hi - lo
            d += timedelta(days=1)
        return tot // 60

    for emp, lst in byemp.items():
        lst.sort()
        kept = []
        for p in lst:
            if kept and kept[-1][4] == p[4] and p[0] - kept[-1][0] <= 300:
                wd = workday(emp, rnd(p[2], p[0]))
                if pstart <= wd <= pend:
                    exc['duplicates_dropped'] += 1
                continue
            kept.append(p)
        rp = [(rnd(p[2], p[0]), p[4], p[2]) for p in kept]
        shifts = []  # (in_r, out_r, site, workday)
        i = 0
        n = len(rp)
        while i < n:
            ep, dr, site = rp[i]
            if dr == 'IN':
                if i + 1 < n and rp[i + 1][1] == 'OUT' and rp[i + 1][0] - ep <= 16 * 3600:
                    shifts.append((ep, rp[i + 1][0], site, workday(emp, ep)))
                    i += 2
                    continue
                wd = workday(emp, ep)
                if pstart <= wd <= pend:
                    exc['open_shifts'] += 1
            else:
                wd = workday(emp, ep)
                if pstart <= wd <= pend:
                    exc['orphan_outs'] += 1
            i += 1
        shifts = [s for s in shifts if pstart <= s[3] <= pend]
        shifts.sort(key=lambda s: s[0])
        day_cum = {}
        week_cum = {}
        r = res[emp]
        for a, b, site, wd in shifts:
            worked = max(0, (b - a) // 60)
            paid = worked - 30 if worked > 360 else worked
            night = min(night_minutes(sites[site][0], a, b), paid)
            c = day_cum.get(wd, 0)
            dot = max(0, c + paid - 480) - max(0, c - 480)
            day_cum[wd] = c + paid
            reg_after = paid - dot
            wk = wd - timedelta(days=wd.weekday())
            w = week_cum.get(wk, 0)
            wot = max(0, w + reg_after - 2400) - max(0, w - 2400)
            week_cum[wk] = w + reg_after
            ot = dot + wot
            regular = paid - ot
            rate = Fraction(0)
            for ef, rt in rates.get(emp, []):
                if ef <= wd:
                    rate = rt
            cents[emp] += rate * (regular + Fraction(3, 2) * ot) / 60 + rate * Fraction(15, 100) * night / 60
            r['shifts'] += 1
            r['paid_minutes'] += paid
            r['overtime_minutes'] += ot
            r['night_minutes'] += night
    tot = dict(shifts=0, paid_minutes=0, overtime_minutes=0, night_minutes=0)
    totc = 0
    for e, r in res.items():
        c = int((cents[e] * 100 + Fraction(1, 2)) // 1)
        r['gross'] = '%d.%02d' % divmod(c, 100)
        totc += c
        for k in tot:
            tot[k] += r[k]
    tot['gross'] = '%d.%02d' % divmod(totc, 100)
    json.dump({'period': {'start': period['start'], 'end': period['end']}, 'employees': res,
               'exceptions': exc, 'totals': tot}, open(outp, 'w'), indent=1)


if __name__ == '__main__':
    main(sys.argv[1], sys.argv[2])
